def normalize_interest(name):
    """Lowercase, trim, collapse whitespace, drop trailing punctuation.

    "  Cooking  " and "cooking" must never become two separate interests.
    """
    text = re.sub(r"\s+", " ", str(name or "").strip().lower())
    text = re.sub(r"[^\w\s\-&']", "", text)
    return text.strip()[:60]


def ensure_interest_rows(pod, names):
    """Normalise interest names, creating catalog rows for new custom interests."""
    wanted = []
    seen = set()
    for raw in names or []:
        key = normalize_interest(raw)
        if key and key not in seen:
            seen.add(key)
            wanted.append(key)
    if not wanted:
        return []
    existing = {str(r["normalized_name"]): r for r in list_rows(pod, "aa_interests", limit=1000)}
    out = []
    for key in wanted:
        row = existing.get(key)
        if not row:
            row = pod.table("aa_interests").create({
                "normalized_name": key,
                "label": key[:1].upper() + key[1:],
                "category": "Custom",
                "is_custom": True,
            })
            existing[key] = row
        out.append(row)
    return out


def directory(pod):
    """One read of every profile-ish row, indexed by account id.

    Shared tables (enable_rls: false) are used deliberately: the compatibility
    engine has to compare two members' profiles, which per-user RLS rows would
    make impossible. Isolation between app accounts is enforced in this API
    layer instead - every handler resolves the caller from a session token and
    only ever returns fields the caller may see.
    """
    profiles = {str(r["account_id"]): r for r in list_rows(pod, "aa_profiles", limit=2000)}
    interests_rows = list_rows(pod, "aa_interests", limit=2000)
    interests_by_id = {str(r["id"]): r for r in interests_rows}
    links = list_rows(pod, "aa_profile_interests", limit=6000)
    profiles_by_id = {str(r["id"]): acc for acc, r in profiles.items()}
    interests_by_account = {}
    for link in links:
        account_id = profiles_by_id.get(str(link["profile_id"]))
        interest = interests_by_id.get(str(link["interest_id"]))
        if account_id and interest:
            interests_by_account.setdefault(account_id, []).append(interest["normalized_name"])
    answers_by_account = {}
    for row in list_rows(pod, "aa_questionnaire_responses", limit=6000):
        answers_by_account.setdefault(str(row["account_id"]), {})[str(row["question_key"])] = decode_json_value(row.get("response_value"))
    prefs_by_account = {str(r["account_id"]): r for r in list_rows(pod, "aa_discovery_preferences", limit=2000)}
    accounts = {str(r["id"]): r for r in list_rows(pod, "aa_accounts", limit=2000)}
    return {
        "profiles": profiles,
        "interests_by_account": interests_by_account,
        "answers_by_account": answers_by_account,
        "prefs_by_account": prefs_by_account,
        "accounts": accounts,
    }


