def question_public_view():
    """Question definitions safe to send to the browser (no scoring internals)."""
    out = []
    for q in QUESTIONS:
        out.append({
            "key": q["key"],
            "dimension": q["dimension"],
            "prompt": q["prompt"],
            "kind": q["kind"],
            "options": q["options"],
            "scale_labels": q.get("scale_labels"),
            "min_selected": q.get("min_selected"),
            "max_selected": q.get("max_selected"),
            "required": False,
        })
    return out


def _as_set(value):
    if value is None:
        return set()
    if isinstance(value, (list, tuple, set)):
        return {str(v).strip().lower() for v in value if str(v).strip()}
    text = str(value).strip()
    if not text:
        return set()
    if "," in text:
        return {part.strip().lower() for part in text.split(",") if part.strip()}
    return {text.lower()}


def ordinal_similarity(a, b):
    """1.0 for the same answer, 0.0 for opposite ends of a 5-point scale."""
    try:
        x, y = float(a), float(b)
    except (TypeError, ValueError):
        return None
    return max(0.0, 1.0 - abs(x - y) / 4.0)


def categorical_similarity(question, a, b):
    av, bv = str(a).strip().lower(), str(b).strip().lower()
    if not av or not bv:
        return None
    if av == bv:
        return 1.0
    pairs = question.get("pairs") or {}
    if (av, bv) in pairs:
        return pairs[(av, bv)]
    if (bv, av) in pairs:
        return pairs[(bv, av)]
    return question.get("default", 0.3)


def multiselect_similarity(a, b):
    sa, sb = _as_set(a), _as_set(b)
    if not sa or not sb:
        return None
    return len(sa & sb) / len(sa | sb)


def answer_similarity(question, a, b):
    """Similarity for one question, or None when it cannot be compared."""
    if a is None or b is None:
        return None
    kind = question["kind"]
    if kind == "ordinal":
        return ordinal_similarity(a, b)
    if kind == "categorical":
        return categorical_similarity(question, a, b)
    if kind == "multiselect":
        return multiselect_similarity(a, b)
    return None


def answer_label(question, value):
    """Human-readable answer, used in explanations (never the raw questionnaire dump)."""
    if value is None:
        return None
    if question["kind"] == "multiselect":
        labels = [o["label"] for o in question["options"] if str(o["value"]).lower() in _as_set(value)]
        return ", ".join(labels) if labels else None
    if question["kind"] == "ordinal":
        try:
            num = int(float(value))
        except (TypeError, ValueError):
            return str(value)
        return (question.get("scale_labels") or {}).get(num) or ORDINAL_LABELS.get(num, str(value))
    for option in question["options"]:
        if str(option["value"]).lower() == str(value).strip().lower():
            return option["label"]
    return str(value)


def describe_difference(question, a, b):
    """A neutral sentence about two different answers - a topic, not a defect."""
    la, lb = answer_label(question, a), answer_label(question, b)
    if not la or not lb:
        return None
    return f"You picked \u201c{la}\u201d and they picked \u201c{lb}\u201d on \u201c{question['prompt']}\u201d."

# ---- ml/affinity/weights.py ----
"""Personalised dimension weights, normalised to sum to 1.0."""

DIMENSIONS = ("shared_interests", "semantic", "communication", "lifestyle")

DIMENSION_META = {
    "shared_interests": {
        "label": "Shared interests",
        "description": "Jaccard overlap of the interest tags you both chose.",
    },
    "semantic": {
        "label": "Interest & bio similarity",
        "description": "TF-IDF cosine over your written descriptions, expanded through a concept lexicon.",
    },
    "communication": {
        "label": "Communication style",
        "description": "Agreement on conversation depth, topics, shared-hobby importance and valued qualities.",
    },
    "lifestyle": {
        "label": "Lifestyle rhythm",
        "description": "Agreement on how you spend free time, planning style and social frequency.",
    },
}

# Illustrative starting point, not empirically validated. Users can change it.
DEFAULT_WEIGHTS = {
    "shared_interests": 0.35,
    "semantic": 0.25,
    "communication": 0.20,
    "lifestyle": 0.20,
}

MIN_WEIGHT_SUM = 1e-6


def normalize_weights(raw):
    """Return weights that sum to 1.0.

    Negative and missing values are treated as 0. Inputs written as percentages
    (summing near 100) are detected and divided by their own total. If nothing
    usable is supplied, the documented defaults are returned.
    """
    values = {}
    for key in DIMENSIONS:
        try:
            value = float((raw or {}).get(key, 0.0) or 0.0)
        except (TypeError, ValueError):
            value = 0.0
        values[key] = max(0.0, value)
    total = sum(values.values())
    if total <= MIN_WEIGHT_SUM:
        return dict(DEFAULT_WEIGHTS)
    return {key: round(values[key] / total, 6) for key in DIMENSIONS}


def weights_to_percent(weights):
    normalised = normalize_weights(weights)
    return {key: int(round(value * 100)) for key, value in normalised.items()}

# ---- ml/affinity/similarity.py ----
"""Similarity primitives: Jaccard, semantic cosine, structured alignment."""



def jaccard(a, b):
    """Jaccard similarity of two interest sets.

    Returns (score, shared, union_size). Both-empty returns (None, [], 0) - an
    explicitly unavailable dimension rather than a zero.
    """
    sa = {x for x in (a or []) if str(x).strip()}
    sb = {x for x in (b or []) if str(x).strip()}
    if not sa or not sb:
        return None, [], 0
    shared = sa & sb
    union = sa | sb
    return len(shared) / len(union), sorted(shared), len(union)


def semantic_similarity(text_a, text_b, corpus=None):
    """Cosine similarity of lexicon-expanded TF-IDF vectors.

    `corpus` should contain both texts plus every other profile in play so the
    IDF weights are meaningful; when it is omitted the pair itself is used.
    Returns (score, available) where score is None when both texts are empty.
    """
    a = (text_a or "").strip()
    b = (text_b or "").strip()
    if not a or not b:
        return None, False
    if not tokenize(a) or not tokenize(b):
        return None, False
    docs = list(corpus or []) + [a, b]
    idf = build_idf(docs)
    score = cosine(tfidf_vector(a, idf), tfidf_vector(b, idf))
    return round(score, 4), True


def dimension_from_answers(answers_a, answers_b, dimension):
    """Mean similarity across the answered questions of one dimension.

    Returns (score, per-question detail, shared_answers, differing_answers).
    Questions either side skipped are omitted, never scored as zero.
    """
    scores = []
    detail = []
    aligned = []
    differences = []
    for question in QUESTIONS:
        if question["dimension"] != dimension:
            continue
        raw_a = answers_a.get(question["key"])
        raw_b = answers_b.get(question["key"])
        similarity = answer_similarity(question, raw_a, raw_b)
        if similarity is None:
            detail.append({"key": question["key"], "prompt": question["prompt"], "status": "missing"})
            continue
        scores.append(similarity)
        label_a = answer_label(question, raw_a)
        label_b = answer_label(question, raw_b)
        entry = {
            "key": question["key"],
            "prompt": question["prompt"],
            "similarity": round(similarity, 3),
            "you": label_a,
            "them": label_b,
        }
        if similarity >= 0.75:
            aligned.append(entry)
        elif similarity <= 0.4:
            entry["note"] = describe_difference(question, raw_a, raw_b)
            differences.append(entry)
        detail.append(entry)
    if not scores:
        return None, detail, aligned, differences
    return round(sum(scores) / len(scores), 4), detail, aligned, differences

# ---- ml/affinity/compatibility.py ----
"""Profile feature extraction and the explainable compatibility score.

Scoring contract
----------------
* Four dimensions, each scored in [0, 1] or marked unavailable.
* A dimension is unavailable when either side lacks the information for it.
  Unavailable dimensions are *excluded from the weighted average and the
  remaining weights are renormalised* - missing data is never scored as zero.
* overall = sum(w_i * s_i for available i) / sum(w_i for available i)
* coverage = sum(w_i for available i) / sum(w_i for all i), reported alongside
  the score as "how much of what matters to you could actually be checked".
* The result is labelled a *preference alignment estimate*, never a probability
  of relationship success.
"""


DIMENSION_ORDER = DIMENSIONS

CONFIDENCE_BANDS = (
    (0.85, "high"),
    (0.60, "moderate"),
    (0.35, "limited"),
    (0.0, "low"),
)


class DimensionScore:
    __slots__ = ("key", "score", "available", "reason", "weight")

    def __init__(self, key, score=None, available=False, reason="", weight=0.0):
        self.key = key
        self.score = score
        self.available = available
        self.reason = reason
        self.weight = weight

    def to_dict(self):
        return {
            "key": self.key,
            "label": DIMENSION_META[self.key]["label"],
            "description": DIMENSION_META[self.key]["description"],
            "score": None if self.score is None else round(self.score, 4),
            "percent": None if self.score is None else int(round(self.score * 100)),
            "available": self.available,
            "reason": self.reason,
            "weight": round(self.weight, 4),
            "weight_percent": int(round(self.weight * 100)),
        }

    def __repr__(self):  # pragma: no cover - debugging aid
        return f"DimensionScore({self.key!r}, score={self.score!r}, available={self.available!r})"


class CompatResult:
    """Everything the UI needs to explain one pair, and nothing it does not."""

    def __init__(self, overall, dimensions, coverage, confidence, shared_interests,
                 interest_overlap_count, union_count, differences, aligned_questions,
                 missing, explanation, semantic_corpus_size=0, feedback_adjustment=0.0,
                 ranked_score=None, highlights=None):
        self.overall = overall
        self.dimensions = dimensions
        self.coverage = coverage
        self.confidence = confidence
        self.shared_interests = shared_interests
        self.interest_overlap_count = interest_overlap_count
        self.union_count = union_count
        self.differences = differences
        self.aligned_questions = aligned_questions
        self.missing = missing
        self.explanation = explanation
        self.semantic_corpus_size = semantic_corpus_size
        self.feedback_adjustment = feedback_adjustment
        self.ranked_score = overall if ranked_score is None else ranked_score
        self.highlights = highlights or []

    def dimension(self, key):
        for dim in self.dimensions:
            if dim.key == key:
                return dim
        return None

    def to_dict(self):
        return {
            "overall": round(self.overall, 2),
            "ranked_score": round(self.ranked_score, 2),
            "label": "Preference alignment estimate",
            "coverage": round(self.coverage, 4),
            "coverage_percent": int(round(self.coverage * 100)),
            "confidence": self.confidence,
            "dimensions": [d.to_dict() for d in self.dimensions],
            "shared_interests": self.shared_interests,
            "interest_overlap_count": self.interest_overlap_count,
            "interest_union_count": self.union_count,
            "differences": self.differences,
            "aligned_questions": self.aligned_questions,
            "missing": self.missing,
            "explanation": self.explanation,
            "highlights": self.highlights,
            "feedback_adjustment": round(self.feedback_adjustment, 2),
            "semantic_corpus_size": self.semantic_corpus_size,
        }


class ProfileFeatures:
    """Normalised profile representation handed to the scorer."""

    __slots__ = ("account_id", "display_name", "interests", "bio", "answers",
                 "age", "city", "discoverable", "onboarding_completed", "connection_type",
                 "demographics")

    def __init__(self, account_id, display_name="", interests=None, bio="",
                 answers=None, age=None, city=None, discoverable=True,
                 onboarding_completed=False, connection_type=None, demographics=None):
        self.account_id = str(account_id)
        self.display_name = display_name or ""
        self.interests = [str(i).strip() for i in (interests or []) if str(i).strip()]
        self.bio = bio or ""
        self.answers = dict(answers or {})
        self.age = age
        self.city = city
        self.discoverable = discoverable
        self.onboarding_completed = onboarding_completed
        self.connection_type = connection_type
        # Explicitly *not* used for scoring: kept only to document that no
        # protected attribute enters the model. Always empty in practice.
        self.demographics = demographics or {}

    @property
    def free_text(self):
        """The text the semantic dimension reads: the bio plus interest labels."""
        parts = [self.bio] + list(self.interests)
        return " ".join(part for part in parts if part)

    def answered_keys(self):
        return {k for k, v in self.answers.items() if v not in (None, "", [])}

    def to_dict(self):
        return {
            "account_id": self.account_id,
            "display_name": self.display_name,
            "interests": self.interests,
            "bio": self.bio,
            "answers": self.answers,
            "age": self.age,
            "city": self.city,
            "discoverable": self.discoverable,
            "onboarding_completed": self.onboarding_completed,
            "connection_type": self.connection_type,
        }


def extract_features(row, interests=None, answers=None):
    """Build ProfileFeatures from a stored profile row plus its interests/answers."""
    if row is None:
        raise ValueError("a profile row is required")
    return ProfileFeatures(
        account_id=row.get("account_id") or row.get("id"),
        display_name=row.get("display_name") or "",
        interests=interests if interests is not None else row.get("interests") or [],
        bio=row.get("bio") or "",
        answers=answers if answers is not None else row.get("answers") or {},
        age=row.get("age"),
        city=row.get("city"),
        discoverable=bool(row.get("discoverable", True)),
        onboarding_completed=bool(row.get("onboarding_completed", False)),
        connection_type=row.get("connection_type"),
    )


def _confidence_for(coverage):
    for threshold, label in CONFIDENCE_BANDS:
        if coverage >= threshold:
            return label
    return "low"


def score_pair(a, b, weights=None, corpus_texts=None, feedback_adjustment=0.0):
    """Score two ProfileFeatures and explain the result.

    Deterministic: identical inputs always produce identical output. No network
    call, no randomness, no LLM.
    """
    w = normalize_weights(weights)

    dims = []
    # 1. Shared interests (Jaccard)
    jac, shared, union_size = jaccard(a.interests, b.interests)
    dims.append(DimensionScore(
        "shared_interests", jac, jac is not None, weight=w["shared_interests"],
        reason="" if jac is not None else "One of you has no interests listed, so overlap cannot be measured.",
    ))

    # 2. Semantic similarity (lexicon-expanded TF-IDF cosine)
    corpus = corpus_texts if corpus_texts is not None else [a.free_text, b.free_text]
    sem, sem_ok = semantic_similarity(a.free_text, b.free_text, corpus)
    dims.append(DimensionScore(
        "semantic", sem, sem_ok, weight=w["semantic"],
        reason="" if sem_ok else "Neither profile has written text to compare.",
    ))

    # 3 & 4. Structured questionnaire dimensions
    aligned, differences = [], []
    for key in ("communication", "lifestyle"):
        score, detail, dim_aligned, dim_diff = dimension_from_answers(a.answers, b.answers, key)
        aligned.extend(dim_aligned)
        differences.extend(dim_diff)
        answered = sum(1 for d in detail if d.get("similarity") is not None or d.get("prompt") and d.get("status") != "missing")
        dims.append(DimensionScore(
            key, score, score is not None, weight=w[key],
            reason="" if score is not None else "Not enough answered questions on both sides to compare this dimension.",
        ))

    available = [d for d in dims if d.available and d.score is not None]
    total_weight = sum(d.weight for d in dims) or 1.0
    available_weight = sum(d.weight for d in available)
    if available:
        overall = sum(d.weight * d.score for d in available) / available_weight
    else:
        overall = 0.0
    coverage = available_weight / total_weight

    missing = [
        {"key": d.key, "label": DIMENSION_META[d.key]["label"], "reason": d.reason}
        for d in dims if not d.available
    ]

    base_score = round(overall * 100.0, 2)
    ranked = max(0.0, min(100.0, base_score + float(feedback_adjustment or 0.0)))

    result = CompatResult(
        overall=base_score,
        dimensions=dims,
        coverage=coverage,
        confidence=_confidence_for(coverage),
        shared_interests=shared,
        interest_overlap_count=len(shared),
        union_count=union_size,
        differences=differences,
        aligned_questions=aligned,
        missing=missing,
        explanation="",
        semantic_corpus_size=len(corpus or []),
        feedback_adjustment=float(feedback_adjustment or 0.0),
        ranked_score=ranked,
    )
    result.explanation = _template_explanation(a, b, result)
    result.highlights = _highlights(result)
    return result


def _top_dimension(result):
    scored = [d for d in result.dimensions if d.available and d.score is not None]
    if not scored:
        return None
    return max(scored, key=lambda d: d.score * (0.5 + d.weight))


def _highlights(result):
    """Two or three short lines: the strongest evidence for this recommendation."""
    out = []
    if result.shared_interests:
        names = ", ".join(result.shared_interests[:3])
        out.append(f"{len(result.shared_interests)} shared interest"
                   f"{'s' if len(result.shared_interests) != 1 else ''}: {names}")
    top = _top_dimension(result)
    if top is not None and top.score >= 0.55:
        out.append(f"{DIMENSION_META[top.key]['label']} aligns at {int(round(top.score * 100))}%")
    if result.aligned_questions:
        out.append(f"{len(result.aligned_questions)} questionnaire answer"
                   f"{'s' if len(result.aligned_questions) != 1 else ''} matched closely")
    if result.missing:
        out.append(f"{len(result.missing)} dimension"
                   f"{'s' if len(result.missing) != 1 else ''} had too little information")
    return out[:3]


def _template_explanation(a, b, result):
    """Deterministic explanation written only from computed facts.

    No generative model is involved, so nothing here can be invented. An LLM may
    later be layered on for tone *after* this text exists, but the evidence lines
    below are the source of truth.
    """
    name = b.display_name or "This person"
    sentences = []

    strong = [d for d in result.dimensions if d.available and d.score is not None and d.score >= 0.6]
    weak = [d for d in result.dimensions if d.available and d.score is not None and d.score < 0.4]

    if result.shared_interests:
        listed = ", ".join(result.shared_interests[:4])
        sentences.append(f"You and {name} both listed {listed}.")
    elif result.dimension("shared_interests").available:
        sentences.append(f"You and {name} do not share any listed interests, so the comparison rests on your written profiles and answers.")

    semantic = result.dimension("semantic")
    if semantic.available and semantic.score and semantic.score >= 0.25:
        sentences.append(
            f"Your written descriptions also overlap in meaning (semantic similarity "
            f"{int(round(semantic.score * 100))}%), which is measured from the text you both wrote, not from shared tags."
        )
    elif semantic.available and semantic.score is not None:
        sentences.append(
            f"Your written descriptions overlap little (semantic similarity {int(round(semantic.score * 100))}%)."
        )

    if strong:
        labels = ", ".join(DIMENSION_META[d.key]["label"].lower() for d in strong[:2])
        sentences.append(f"The strongest alignment is in {labels}.")
    if result.aligned_questions:
        q = result.aligned_questions[0]
        sentences.append(f"On \u201c{q['prompt']}\u201d your answers were close.")
    if weak:
        labels = ", ".join(DIMENSION_META[d.key]["label"].lower() for d in weak[:2])
        sentences.append(f"{labels.capitalize()} differ more than the rest \u2014 a useful thing to talk about early.")
    if result.missing:
        labels = ", ".join(m["label"].lower() for m in result.missing[:2])
        sentences.append(f"There is not enough information to compare {labels}.")
    if not sentences:
        sentences.append("Both profiles are too thin to compare meaningfully yet.")
    return " ".join(sentences)

# ---- ml/affinity/starters.py ----
"""Conversation starters derived from real shared interests.

Every starter is a template keyed by the shared interest. Nothing is invented
about either person: the text is a question, not a claim. When an interest has no
curated template, a neutral template is used that still names the interest.
"""

TEMPLATES = {
    "photography": "What kind of places do you most enjoy photographing?",
    "technology": "What is a technology project you have enjoyed exploring recently?",
    "cooking": "If you could learn one dish from any country, which would it be?",
    "food": "What is a meal you would happily travel for?",
    "travel": "Which trip changed how you see things the most?",
    "music": "What is a song or album you keep coming back to?",
    "books": "What is a book you wish you could read again for the first time?",
    "reading": "What have you been reading lately that stayed with you?",
    "fitness": "What does a good training week look like for you?",
    "hiking": "Which trail or walk would you recommend to someone who has never tried it?",
    "outdoors": "What is your favourite way to spend a day outside?",
    "art": "What kind of art do you seek out when you travel?",
    "gaming": "Which game do you think more people should try?",
    "film": "What film would you put on for someone who has not seen it?",
    "volunteering": "What kind of volunteering has felt most worthwhile to you?",
    "entrepreneurship": "What is an idea you would build if you had a free month?",
    "learning": "What is something you have learned recently that surprised you?",
    "gardening": "What are you growing, or what would you like to grow?",
    "pets": "Tell me about the animal that runs your household.",
    "mindfulness": "What helps you switch off after a long week?",
    "dance": "Is there a style of dance you would love to learn?",
    "nightlife": "What makes a good night out for you?",
}

GENERIC_TEMPLATES = [
    "What got you into {interest} in the first place?",
    "What is the best thing about {interest} for you right now?",
    "If you had a free afternoon for {interest}, what would you do with it?",
]


def conversation_starters(shared_interests, limit=4):
    """One starter per shared interest, plus nothing invented about the person."""
    out = []
    for index, interest in enumerate(shared_interests or []):
        key = str(interest).strip().lower()
        template = TEMPLATES.get(key)
        if template:
            text = template
        else:
            text = GENERIC_TEMPLATES[index % len(GENERIC_TEMPLATES)].format(interest=key)
        out.append({"interest": interest, "text": text, "source": "shared_interest"})
        if len(out) >= limit:
            break
    return out

# ---- ml/affinity/explain.py ----
"""Explanation helpers exposed to the API layer."""



def explain_result(result):
    """Return the explanation payload for one computed pair.

    Everything is derived from the CompatResult: no extra inference, no LLM.
    """
    return {
        "summary": result.explanation,
        "highlights": result.highlights,
        "why_recommended": _why(result),
        "aligned": [
            {"key": d.key, "label": DIMENSION_META[d.key]["label"], "percent": d.to_dict()["percent"]}
            for d in result.dimensions if d.available and d.score is not None and d.score >= 0.6
        ],
        "differences": result.differences,
        "missing": result.missing,
        "starters": conversation_starters(result.shared_interests),
        "calculation": _calculation(result),
    }


def _why(result):
    """One line naming the concrete reason this profile surfaced."""
    if result.shared_interests:
        return (f"Ranked on a preference alignment estimate of {int(round(result.overall))}% "
                f"with {len(result.shared_interests)} shared interest"
                f"{'s' if len(result.shared_interests) != 1 else ''}.")
    strongest = max(
        (d for d in result.dimensions if d.available and d.score is not None),
        key=lambda d: d.score,
        default=None,
    )
    if strongest is None:
        return "Both profiles are too incomplete to rank meaningfully."
    return (f"Ranked on a preference alignment estimate of {int(round(result.overall))}% "
            f"led by {DIMENSION_META[strongest.key]['label'].lower()} "
            f"({strongest.to_dict()['percent']}%).")


def _calculation(result):
    """The exact arithmetic behind the number, so it is auditable in the UI."""
    parts = []
    numerator = 0.0
    denominator = 0.0
    for d in result.dimensions:
        if d.available and d.score is not None:
            numerator += d.weight * d.score
            denominator += d.weight
            parts.append({
                "dimension": DIMENSION_META[d.key]["label"],
                "weight": round(d.weight, 4),
                "score": round(d.score, 4),
                "contribution": round(d.weight * d.score, 4),
            })
    return {
        "formula": "overall = sum(weight_i * score_i) / sum(weight_i) over dimensions with data",
        "components": parts,
        "numerator": round(numerator, 4),
        "denominator": round(denominator, 4),
        "overall": round(result.overall, 2),
        "coverage_percent": int(round(result.coverage * 100)),
        "missing_handling": ("Dimensions without enough information are dropped from both the "
                             "numerator and the denominator, then the remaining weights are "
                             "renormalised. They are never counted as zero."),
        "feedback_adjustment": round(result.feedback_adjustment, 2),
        "ranked_score": round(result.ranked_score, 2),
        "disclaimer": ("This is a preference alignment estimate computed from the profile fields "
                       "you both filled in. It is not a prediction of relationship success and "
                       "has not been validated as one."),
    }

# ---- ml/affinity/ranking.py ----
"""Candidate eligibility, feedback adjustment and recommendation ranking.

Ranking rules, in order:
1. Hard eligibility filters (self, undiscoverable, incomplete onboarding, age
   preference, blocks in either direction, already liked/passed).
2. Minimum information: at least one comparable dimension must exist, otherwise
   the pair is dropped with a reason instead of being shown at a fake score.
3. Score = preference alignment estimate + a small, bounded, explicit
   personalisation adjustment from the user's own feedback.
4. Tie-break on information coverage, then on a stable hash of the pair (never on
   popularity, age, gender or profile completeness).
5. Diversity pass: at most MAX_SAME_TOP_INTEREST profiles whose strongest shared
   interest is the same one, so the feed is not a monoculture.
"""

import hashlib


MIN_DIMENSIONS = 1
MAX_SAME_TOP_INTEREST = 2
FEEDBACK_PER_MATCH = 1.5
FEEDBACK_CAP = 6.0

POSITIVE_FEEDBACK = {"matches_interests", "more_like_this"}
NEGATIVE_FEEDBACK = {"not_relevant", "does_not_align"}


def _stable_tiebreak(a_id, b_id):
    raw = "|".join(sorted([str(a_id), str(b_id)]))
    return int(hashlib.sha256(raw.encode("utf-8")).hexdigest()[:8], 16)


class CandidateDecision:
    """Why a candidate was included or excluded - surfaced in the UI, not logged away."""

    __slots__ = ("account_id", "eligible", "reason")

    def __init__(self, account_id, eligible, reason=""):
        self.account_id = account_id
        self.eligible = eligible
        self.reason = reason

    def to_dict(self):
        return {"account_id": self.account_id, "eligible": self.eligible, "reason": self.reason}


def eligibility(me, candidate, prefs=None, blocked_ids=None, interacted_ids=None):
    """Return (eligible, reason). Pure function, easy to test."""
    prefs = prefs or {}
    blocked = blocked_ids or set()
    interacted = interacted_ids or set()
    cid = str(candidate.account_id)

    if cid == str(me.account_id):
        return CandidateDecision(cid, False, "This is your own profile.")
    if cid in {str(b) for b in blocked}:
        return CandidateDecision(cid, False, "Blocked in one direction or the other.")
    if not candidate.onboarding_completed:
        return CandidateDecision(cid, False, "Their profile is not complete yet.")
    if not candidate.discoverable:
        return CandidateDecision(cid, False, "They have turned profile discovery off.")

    connection = prefs.get("connection_type")
    if connection and connection != "any" and candidate.connection_type and candidate.connection_type != connection:
        return CandidateDecision(cid, False, f"They are looking for {candidate.connection_type.replace('_', ' ')}.")

    min_age = prefs.get("min_age")
    max_age = prefs.get("max_age")
    if candidate.age is not None:
        if min_age and candidate.age < int(min_age):
            return CandidateDecision(cid, False, "Younger than your preferred age range.")
        if max_age and candidate.age > int(max_age):
            return CandidateDecision(cid, False, "Older than your preferred age range.")

    if cid in {str(i) for i in interacted}:
        return CandidateDecision(cid, False, "You have already liked or passed on this profile.")
    return CandidateDecision(cid, True, "")


def feedback_adjustment(me, candidate, feedback_rows, my_interests_by_target=None):
    """Bounded, explainable nudge from the user's own explicit feedback.

    For every earlier feedback item the user gave, if this candidate shares at
    least one interest with that earlier profile the adjustment moves by
    +/- FEEDBACK_PER_MATCH, capped at FEEDBACK_CAP points. It is shown in the
    explanation as "personalisation adjustment" and never overrides blocks or
    eligibility (eligibility runs first).
    """
    if not feedback_rows:
        return 0.0
    mine = {str(i).lower() for i in (candidate.interests or [])}
    total = 0.0
    for row in feedback_rows:
        kind = str(row.get("feedback_type") or "")
        target = str(row.get("target_account_id") or "")
        if not target or not mine:
            continue
        target_interests = {
            str(i).lower() for i in (my_interests_by_target or {}).get(target, [])
        }
        if not (mine & target_interests):
            continue
        if kind in POSITIVE_FEEDBACK:
            total += FEEDBACK_PER_MATCH
        elif kind in NEGATIVE_FEEDBACK:
            total -= FEEDBACK_PER_MATCH
    return max(-FEEDBACK_CAP, min(FEEDBACK_CAP, total))


def rank_candidates(me, candidates, prefs=None, weights=None, blocked_ids=None,
                    interacted_ids=None, feedback_rows=None, corpus_texts=None,
                    limit=12, offset=0, excluded=None):
    """Score, filter, rank and paginate. Returns (items, meta)."""
    prefs = prefs or {}
    excluded = excluded or set()
    decisions = []
    scored = []
    interests_by_target = {
        str(c.account_id): c.interests for c in candidates
    }

    for candidate in candidates:
        cid = str(candidate.account_id)
        if cid in {str(e) for e in excluded}:
            decisions.append(CandidateDecision(cid, False, "Already shown in this discovery session."))
            continue
        decision = eligibility(me, candidate, prefs, blocked_ids, interacted_ids)
        if not decision.eligible:
            decisions.append(decision)
            continue
        adjustment = feedback_adjustment(me, candidate, feedback_rows or [], interests_by_target)
        result = score_pair(me, candidate, weights, corpus_texts, adjustment)
        available = [d for d in result.dimensions if d.available and d.score is not None]
        if len(available) < MIN_DIMENSIONS:
            decisions.append(CandidateDecision(
                cid, False, "Not enough information on either profile to estimate alignment."))
            continue
        decisions.append(CandidateDecision(cid, True, ""))
        scored.append((result, candidate))

    scored.sort(key=lambda pair: (
        -round(pair[0].ranked_score, 2),
        -round(pair[0].coverage, 4),
        _stable_tiebreak(me.account_id, pair[1].account_id),
    ))

    # Diversity pass: defer a profile when its top shared interest is already
    # represented MAX_SAME_TOP_INTEREST times higher up the list.
    balanced = []
    deferred = []
    seen_top = {}
    for result, candidate in scored:
        top = result.shared_interests[0].lower() if result.shared_interests else "__none__"
        count = seen_top.get(top, 0)
        if count >= MAX_SAME_TOP_INTEREST:
            deferred.append((result, candidate))
            continue
        seen_top[top] = count + 1
        balanced.append((result, candidate))
    balanced.extend(deferred)

    total = len(balanced)
    page = balanced[offset:offset + limit]
    items = []
    for rank, (result, candidate) in enumerate(page, start=offset + 1):
        items.append({"rank": rank, "candidate": candidate, "result": result})

    meta = {
        "total_eligible": total,
        "returned": len(items),
        "offset": offset,
        "limit": limit,
        "has_more": offset + limit < total,
        "candidates_considered": len(candidates),
        "excluded": [d.to_dict() for d in decisions if not d.eligible],
        "algorithm": "content-based scoring on structured + semantic features, personalised weights",
        "minimum_dimensions": MIN_DIMENSIONS,
    }
    return items, meta

